import React, { useState } from 'react';
import { Search, Calculator, DollarSign, BarChart3, TrendingUp } from 'lucide-react';

export const TAB_CONFIG = {
  id: 'home',
  title: 'Home',
  description: 'Dashboard and overview of all financial formulas and tools'
};

/**
 * Home Tab - Dashboard for Financial Formula Suite
 */
export default function HomeTab({ selectTab }) {
  const [searchQuery, setSearchQuery] = useState('');

  const quickLinks = [
    { id: 'compound-interest', title: 'Compound Interest', icon: Calculator, description: 'Calculate compound interest growth over time' },
    { id: 'present-value', title: 'Present Value', icon: DollarSign, description: 'Calculate present value of future cash flows' },
    { id: 'net-present-value', title: 'Net Present Value', icon: BarChart3, description: 'Investment analysis with NPV calculation' }
  ];

  const handleQuickLinkClick = (linkId) => {
    if (selectTab) {
      selectTab(linkId);
    }
  };

  return (
    <div className="space-y-8">
      {/* Welcome Section */}
      <div className="text-center">
        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-gradient-to-r from-red-500/20 to-red-600/20 glow-red mb-4">
          <TrendingUp className="w-8 h-8 text-red-600 dark:text-red-400" />
        </div>
        <h1 className="text-3xl font-light tracking-wide text-gray-900 dark:text-white mb-3">
          Financial Formula Suite
        </h1>
        <p className="text-lg text-gray-600 dark:text-gray-400 font-light max-w-2xl mx-auto">
          Comprehensive library of financial formulas and calculators designed to help you analyze investments,
          calculate risks, and make informed financial decisions.
        </p>
      </div>

      {/* Search Bar */}
      <div className="max-w-md mx-auto">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search formulas and tools..."
            className="w-full pl-10 pr-4 py-3 rounded-xl bg-white/10 dark:bg-black/20 border border-white/20
                     text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400
                     focus:outline-none focus:ring-2 focus:ring-red-500/30 focus:border-red-400/50
                     backdrop-blur-sm font-light tracking-wide"
          />
        </div>
        {searchQuery && (
          <div className="mt-2 text-sm text-gray-500 dark:text-gray-400 text-center">
            Search functionality coming soon...
          </div>
        )}
      </div>

      {/* Quick Links */}
      <div>
        <h2 className="text-xl font-light tracking-wide text-gray-900 dark:text-white mb-4">
          Quick Access
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {quickLinks.map((link) => {
            const Icon = link.icon;
            return (
              <button
                key={link.id}
                onClick={() => handleQuickLinkClick(link.id)}
                className="p-4 rounded-xl bg-white/5 dark:bg-black/20 backdrop-blur-sm border border-white/10
                         hover:bg-white/10 dark:hover:bg-black/30 hover:border-red-200/30
                         transition-all duration-200 text-left group focus:outline-none focus:ring-2 focus:ring-red-500/30"
              >
                <div className="flex items-start gap-3">
                  <div className="p-2 rounded-lg bg-red-500/10 group-hover:bg-red-500/20 transition-colors">
                    <Icon className="w-5 h-5 text-red-600 dark:text-red-400" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <h3 className="font-medium text-gray-900 dark:text-white mb-1">
                      {link.title}
                    </h3>
                    <p className="text-sm text-gray-600 dark:text-gray-400 font-light">
                      {link.description}
                    </p>
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}
